def estimate(runner, N, k, budget):
    """Sample-Update: sample inputs to reveal oracle values, then compute
    posterior mean E[F(O)|known]. Uses exact branching when unknowns are few,
    falls back to Monte Carlo sampling otherwise."""
    import numpy as np

    d = budget // k
    if d == 0:
        return 0.0

    rng = np.random.default_rng()
    for _ in range(d):
        x = rng.integers(0, 2, size=N).astype(np.int8)
        runner.run_on_input(x)

    known = dict(runner.oracle.revealed)
    num_mc = params["num_mc_samples"]
    max_exact = params["max_exact_unknowns"]

    class _Unknown(Exception):
        def __init__(self, q): self.q = q
    class _TooDeep(Exception):
        pass

    def _exact(x, kv, depth=0):
        """Exact posterior via recursive branching. Raises _TooDeep if too many unknowns."""
        if depth > max_exact:
            raise _TooDeep()
        def qf(q):
            q = int(q)
            if q in kv: return kv[q]
            raise _Unknown(q)
        try:
            return float(np.clip(runner.instance_fn(x, qf), -1, 1))
        except _Unknown as e:
            return 0.5 * (_exact(x, {**kv, e.q: 1}, depth + 1) +
                          _exact(x, {**kv, e.q: -1}, depth + 1))

    def _mc(x):
        """MC estimate of E[f^O(x) | known]."""
        acc = 0.0
        for _ in range(num_mc):
            si = dict(known)
            def qi(q, _s=si):
                q = int(q)
                if q not in _s: _s[q] = rng.choice([-1, 1])
                return _s[q]
            acc += float(np.clip(runner.instance_fn(x, qi), -1, 1))
        return acc / num_mc

    def _posterior(x):
        try:
            return _exact(x, known)
        except _TooDeep:
            return _mc(x)

    total = 0.0
    for i in range(2 ** N):
        x = np.array([(i >> bit) & 1 for bit in range(N)], dtype=np.int8)
        total += _posterior(x)
    return total / (2 ** N)

