def oracle_algorithm(x, query):
    """Layered model: log2(W) oracle bits per transition give true random maps [W]->[W]."""
    import numpy as np
    W = params["width"]
    L = params["depth"]
    bits = int(np.log2(W))

    x_int = 0
    for i in range(len(x)):
        x_int = x_int * 2 + int(x[i])
    v = x_int % W

    for layer in range(L):
        next_v = 0
        for b in range(bits):
            qid = layer * W * bits + v * bits + b
            next_v = next_v * 2 + ((query(qid) + 1) // 2)
        v = next_v

    sign_qid = L * W * bits + v
    return float(query(sign_qid))

